<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#F07178;">input</span><span style="color:#89DDFF;"> :value=&quot;value&quot; @input=&quot;$emit(&#39;input&#39;, $event.target.value)&quot; /&gt;</span></span>
